302	func TestRegistryHealthStaleAndSameSequence(t *testing.T) {
303		r := NewRegistry()
304		registerService(t, r, "svc", 0, []Instance{{ID: "a", Address: "h:1"}})
305	
306		upd, _ := r.ValidateHealth("svc", "a", 1, 5, false, "down")
307		r.ApplyHealth(upd)
308	
309		// Older sequence is stale and reports the current sequence.
310		upd, _ = r.ValidateHealth("svc", "a", 1, 4, true, "")
311		out := r.ApplyHealth(upd)
312		if out.OK || out.Kind != OutcomeStale || out.Sequence != 5 {
313			t.Fatalf("stale: %+v", out)
314		}
315		// State unchanged.
316		inst := instanceHealth(t, r, "svc", "a")
317		if inst.Health != HealthUnhealthy || inst.Sequence != 5 {
318			t.Fatalf("state changed after stale: %+v", inst)
319		}
320	
321		// Same sequence with identical normalized content succeeds without change.
322		upd, _ = r.ValidateHealth("svc", "a", 1, 5, false, "  down  ")
323		out = r.ApplyHealth(upd)
324		if !out.OK || out.Changed || out.Sequence != 5 {
325			t.Fatalf("same idempotent: %+v", out)
326		}
327	
328		// Same sequence with different status conflicts.
329		upd, _ = r.ValidateHealth("svc", "a", 1, 5, true, "")
330		out = r.ApplyHealth(upd)
331		if out.OK || out.Kind != OutcomeConflict || out.Sequence != 5 {
332			t.Fatalf("same seq different status: %+v", out)
333		}
334	
335		// Same sequence with a different reason conflicts.
336		upd, _ = r.ValidateHealth("svc", "a", 1, 5, false, "different reason")
337		out = r.ApplyHealth(upd)
338		if out.OK || out.Kind != OutcomeConflict {
339			t.Fatalf("same seq different reason: %+v", out)
340		}
341	
342		// State must still be the original observation.
343		inst = instanceHealth(t, r, "svc", "a")
344		if inst.Health != HealthUnhealthy || inst.Sequence != 5 || inst.Reason != "down" {
345			t.Fatalf("state mutated after failed same-seq: %+v", inst)
346		}
347	}
