1088	// TestEmptyListReplacementKeepsRotationAndDropsHealth is the regression guard
1089	// for replacing a service's instance list with an empty one and later
1090	// re-adding the very same ids and addresses: the empty list must not delete
1091	// the service or its rotation position, and the re-added instances must not
1092	// recover the health observations recorded before the clear. The batch walks
1093	// the full lifecycle:
1094	//
1095	//   - a, b, c registered at revision 1; a and b observed healthy, c observed
1096	//     unhealthy with a reason, all at sequences above 1;
1097	//   - two successful selections return a then b, leaving the cursor on b;
1098	//   - a replacement with an empty instance list succeeds, reports changed and
1099	//     bumps the revision to 2; the service survives, so a selection at
1100	//     revision 2 is no_healthy (never not_found) and names neither an old
1101	//     instance id nor an old address;
1102	//   - re-registering the original ids and addresses at revision 2 bumps the
1103	//     revision to 3; all three instances are back to unknown at sequence 0
1104	//     with no reason, so nothing is selectable yet;
1105	//   - health observations sent under the pre-clear revisions conflict even
1106	//     with larger sequences, naming the request and current revisions, and
1107	//     restore no eligibility; fresh observations at revision 3 with sequence 1
1108	//     succeed without bumping the registration revision;
1109	//   - the next successful selection continues just after b and returns c with
1110	//     its current address and sequence 1, and only the following one wraps
1111	//     back to a — the failed selections in between never moved the cursor.
1112	//
1113	// The batch contains failures, so the exit status is 1; the failed items keep
1114	// their result slots and the final list is sorted by id and reflects only the
1115	// newly accepted observations.
1116	func TestEmptyListReplacementKeepsRotationAndDropsHealth(t *testing.T) {
1117		input := `{"requests":[
1118			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"a","address":"h1:1"},{"id":"b","address":"h2:2"},{"id":"c","address":"h3:3"}]},
1119			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":11,"healthy":true},
1120			{"type":"health","service":"svc","instanceId":"b","expectedRevision":1,"sequence":12,"healthy":true},
1121			{"type":"health","service":"svc","instanceId":"c","expectedRevision":1,"sequence":13,"healthy":false,"reason":"心跳超时"},
1122			{"type":"select","service":"svc","expectedRevision":1},
1123			{"type":"select","service":"svc","expectedRevision":1},
1124			{"type":"register","service":"svc","expectedRevision":1,"instances":[]},
1125			{"type":"select","service":"svc","expectedRevision":2},
1126			{"type":"register","service":"svc","expectedRevision":2,"instances":[{"id":"a","address":"h1:1"},{"id":"b","address":"h2:2"},{"id":"c","address":"h3:3"}]},
1127			{"type":"select","service":"svc","expectedRevision":3},
1128			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":99,"healthy":true},
1129			{"type":"health","service":"svc","instanceId":"b","expectedRevision":2,"sequence":98,"healthy":true},
1130			{"type":"health","service":"svc","instanceId":"c","expectedRevision":1,"sequence":97,"healthy":true},
1131			{"type":"select","service":"svc","expectedRevision":3},
1132			{"type":"health","service":"svc","instanceId":"a","expectedRevision":3,"sequence":1,"healthy":true},
1133			{"type":"health","service":"svc","instanceId":"b","expectedRevision":3,"sequence":1,"healthy":true},
1134			{"type":"health","service":"svc","instanceId":"c","expectedRevision":3,"sequence":1,"healthy":true},
1135			{"type":"select","service":"svc","expectedRevision":3},
1136			{"type":"select","service":"svc","expectedRevision":3}
1137		]}`
1138		out, code := runRegisterWith(t, input)
1139		if code != 1 {
1140			t.Fatalf("batch contains failures, exit code: %d, output: %s", code, out)
1141		}
1142		var got registerOutput
1143		if err := json.Unmarshal([]byte(out), &got); err != nil {
1144			t.Fatalf("output is not JSON: %v\n%s", err, out)
1145		}
1146		// One result per request, in input order; failed items keep their slots.
1147		if len(got.Results) != 19 {
1148			t.Fatalf("results: %+v", got.Results)
1149		}
1150		// 0: registration accepted at revision 1.
1151		if r := got.Results[0]; !r.OK || !r.Changed || r.Revision != 1 {
1152			t.Fatalf("result 0: %+v", r)
1153		}
1154		// 1-3: observations accepted without bumping the registration revision.
1155		if r := got.Results[1]; !r.OK || !r.Changed || r.Revision != 1 || r.Sequence != 11 {
1156			t.Fatalf("result 1: %+v", r)
1157		}
1158		if r := got.Results[2]; !r.OK || !r.Changed || r.Revision != 1 || r.Sequence != 12 {
1159			t.Fatalf("result 2: %+v", r)
1160		}
1161		if r := got.Results[3]; !r.OK || !r.Changed || r.Revision != 1 || r.Sequence != 13 {
1162			t.Fatalf("result 3: %+v", r)
1163		}
1164		// 4-5: the first two selections rotate a then b; the cursor rests on b.
1165		if r := got.Results[4]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 11 || r.Revision != 1 {
1166			t.Fatalf("result 4: %+v", r)
1167		}
1168		if r := got.Results[5]; !r.OK || r.InstanceID != "b" || r.Address != "h2:2" || r.Sequence != 12 || r.Revision != 1 {
1169			t.Fatalf("result 5: %+v", r)
1170		}
1171		// 6: clearing the instance list succeeds, reports the change and bumps the
1172		// revision to 2.
1173		if r := got.Results[6]; !r.OK || !r.Changed || r.Revision != 2 {
1174			t.Fatalf("result 6: %+v", r)
1175		}
1176		// 7: the empty list keeps the service alive at revision 2, so the answer is
1177		// no_healthy — never not_found — with a readable reason, the current
1178		// revision, and no leftover instance id or address from before the clear.
1179		if r := got.Results[7]; r.OK || r.Error != "no_healthy" || r.Reason == "" ||
1180			r.Revision != 2 || r.InstanceID != "" || r.Address != "" {
1181			t.Fatalf("result 7 no_healthy on empty list: %+v", r)
1182		}
1183		// 8: re-adding the original ids and addresses succeeds and bumps the
1184		// revision to 3.
1185		if r := got.Results[8]; !r.OK || !r.Changed || r.Revision != 3 {
1186			t.Fatalf("result 8: %+v", r)
1187		}
1188		// 9: identical ids and addresses do not bring the old observations back:
1189		// all three instances are unknown again, so the selection is no_healthy.
1190		if r := got.Results[9]; r.OK || r.Error != "no_healthy" || r.Reason == "" ||
1191			r.Revision != 3 || r.InstanceID != "" || r.Address != "" {
1192			t.Fatalf("result 9 no_healthy after re-register: %+v", r)
1193		}
1194		// 10-12: observations under the pre-clear revisions conflict even though
1195		// their sequences exceed the old accepted ones; each names the request and
1196		// current revisions and restores no eligibility.
1197		if r := got.Results[10]; r.OK || r.Error != "conflict" || r.Reason == "" ||
1198			r.ExpectedRevision != 1 || r.ActualRevision != 3 || r.Revision != 3 {
1199			t.Fatalf("result 10 stale-revision report: %+v", r)
1200		}
1201		if r := got.Results[11]; r.OK || r.Error != "conflict" || r.Reason == "" ||
1202			r.ExpectedRevision != 2 || r.ActualRevision != 3 || r.Revision != 3 {
1203			t.Fatalf("result 11 stale-revision report: %+v", r)
1204		}
1205		if r := got.Results[12]; r.OK || r.Error != "conflict" || r.Reason == "" ||
1206			r.ExpectedRevision != 1 || r.ActualRevision != 3 || r.Revision != 3 {
1207			t.Fatalf("result 12 stale-revision report: %+v", r)
1208		}
1209		// 13: the conflicting reports healed nothing — still no_healthy, and this
1210		// failed selection must not move the cursor either.
1211		if r := got.Results[13]; r.OK || r.Error != "no_healthy" ||
1212			r.Revision != 3 || r.InstanceID != "" || r.Address != "" {
1213			t.Fatalf("result 13 still no_healthy: %+v", r)
1214		}
1215		// 14-16: at the current revision a sequence of 1 suffices (the reset
1216		// dropped the old sequences 11-13); health reports never bump the
1217		// registration revision, which stays 3.
1218		if r := got.Results[14]; !r.OK || !r.Changed || r.Revision != 3 || r.Sequence != 1 {
1219			t.Fatalf("result 14: %+v", r)
1220		}
1221		if r := got.Results[15]; !r.OK || !r.Changed || r.Revision != 3 || r.Sequence != 1 {
1222			t.Fatalf("result 15: %+v", r)
1223		}
1224		if r := got.Results[16]; !r.OK || !r.Changed || r.Revision != 3 || r.Sequence != 1 {
1225			t.Fatalf("result 16: %+v", r)
1226		}
1227		// 17: the cursor survived the empty list on b, so the rotation continues
1228		// just after b and returns c with its current address and new sequence.
1229		if r := got.Results[17]; !r.OK || r.InstanceID != "c" || r.Address != "h3:3" || r.Sequence != 1 || r.Revision != 3 {
1230			t.Fatalf("result 17 should resume after b at c: %+v", r)
1231		}
1232		// 18: only now does the rotation wrap back to a.
1233		if r := got.Results[18]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 1 || r.Revision != 3 {
1234			t.Fatalf("result 18 should wrap to a: %+v", r)
1235		}
1236	
1237		// The final list keeps the service at revision 3 with the instances sorted
1238		// by id, all healthy at sequence 1 from the newly accepted observations;
1239		// c's pre-clear unhealthy reason is gone.
1240		if len(got.Services) != 1 {
1241			t.Fatalf("services: %+v", got.Services)
1242		}
1243		svc := got.Services[0]
1244		if svc.Service != "svc" || svc.Revision != 3 {
1245			t.Fatalf("service view: %+v", svc)
1246		}
1247		if len(svc.Instances) != 3 {
1248			t.Fatalf("instances: %+v", svc.Instances)
1249		}
1250		wantInsts := []registerInstance{
1251			{ID: "a", Address: "h1:1", Health: "healthy", Sequence: 1},
1252			{ID: "b", Address: "h2:2", Health: "healthy", Sequence: 1},
1253			{ID: "c", Address: "h3:3", Health: "healthy", Sequence: 1},
1254		}
1255		for i, want := range wantInsts {
1256			if svc.Instances[i] != want {
1257				t.Fatalf("instance %d: got %+v want %+v", i, svc.Instances[i], want)
